[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$TaskDirectory,[Parameter(Mandatory=$true)][string]$FactorsJson,[string]$Reason='assessment')
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'PipelineProtocolV2.psm1') -Force;$f=Get-Content -Raw $FactorsJson|ConvertFrom-Json;$names=@('files','components','contracts_data','runtime_risk','coordination','uncertainty');$sum=0;$nested=[ordered]@{};foreach($n in $names){if($f.PSObject.Properties.Name -notcontains $n){throw "Missing factor $n"};$x=$f.$n;if($x.PSObject.Properties.Name -notcontains 'score' -or @($x.evidence_refs).Count -eq 0){throw "Factor $n requires score and evidence_refs"};$v=[int]$x.score;if($v -lt 0 -or $v -gt 3){throw "Factor $n score must be 0..3"};$nested[$n]=[pscustomobject]@{score=$v;evidence_refs=@($x.evidence_refs)};$sum+=$v};$floor='small';if($f.public_contract -or $f.metadata_data -or $f.rights_rls -or $f.transaction -or $f.background -or $f.integration -or $f.deploy -or $f.protected_tooling){$floor='medium'};if($f.migration -or $f.security -or $f.irreversible -or $f.cross_source -or $f.shared_mutable -or $f.protocol_transition){$floor='large'};if($f.unbounded_irreversible_production){$floor='critical'};$score=if($sum -ge 13){'critical'}elseif($sum -ge 8){'large'}elseif($sum -ge 3){'medium'}else{'small'};$rank=@{'small'=0;'medium'=1;'large'=2;'critical'=3};$level=if($rank[$score] -ge $rank[$floor]){$score}else{$floor};$dir=Join-Path $TaskDirectory 'complexity-revisions';[IO.Directory]::CreateDirectory($dir)|Out-Null;$n=1;while($true){$id='CMP-{0:D4}' -f $n;$file=Join-Path $dir "$id.json";try{$assessment=[ordered]@{protocol_version=2;revision_id=$id;reason=$Reason;factors=$nested;score=$sum;floor=$floor;effective_level=$level;created_at=[datetime]::UtcNow.ToString('o')};Write-PipelineImmutableJson $file $assessment|Out-Null;break}catch{$n++}};$hash=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant();Write-AtomicJson (Join-Path $TaskDirectory 'complexity-current.json') ([ordered]@{protocol_version=2;type='complexity';revision_id=$id;path=(Join-Path 'complexity-revisions' "$id.json");sha256=$hash});$assessment|ConvertTo-Json -Depth 20
